import{_ as t,o as a,c as o,a0 as s}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"Skill tree","description":"","frontmatter":{},"headers":[],"relativePath":"skills.md","filePath":"skills.md","lastUpdated":1791422245000}'),l={name:"skills.md"};function i(d,e,r,n,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="skill-tree" tabindex="-1">Skill tree <a class="header-anchor" href="#skill-tree" aria-label="Permalink to &quot;Skill tree&quot;">​</a></h1><p>The package ships a skill tree under <code>skills/</code>; pi loads it through the <code>skills</code> entry in the <code>pi</code> manifest in <code>package.json</code> when the package is installed (convention directories are not auto-discovered while a <code>pi</code> manifest is present). Tracked skills are mirrored from upstream repos; <a href="/pi-extensions/glossary.html">the glossary</a> holds the domain language (Skill tree, Skill source, Source pin, Skill sync, Adopt, Upstream orphan, Local tweak).</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p><code>skills/&lt;source-slug&gt;/&lt;upstream path&gt;</code> for tracked skills, and <code>skills/local/&lt;name&gt;</code> for local-only skills. The layout mirrors each upstream repo, so a tracked skill&#39;s upstream path is read off its local path. A source may bucket its skills or hold them flat:</p><ul><li><code>skills/mattpocock/engineering/tdd</code> - bucketed (<code>engineering/tdd</code> upstream)</li><li><code>skills/anti-slop/antislop-ui</code> - flat (<code>antislop-ui</code> upstream)</li></ul><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Slug</th><th>Upstream</th><th>License</th><th>Local root</th></tr></thead><tbody><tr><td><code>mattpocock</code></td><td><a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">mattpocock/skills</a></td><td>MIT, upstream <code>LICENSE</code> ships at <code>skills/mattpocock/LICENSE</code></td><td><code>skills/mattpocock/</code></td></tr><tr><td><code>anti-slop</code></td><td><a href="https://github.com/miqdadbadjuber/Anti-Slop" target="_blank" rel="noreferrer">miqdadbadjuber/Anti-Slop</a></td><td>MIT, upstream <code>LICENSE</code> ships at <code>skills/anti-slop/LICENSE</code></td><td><code>skills/anti-slop/</code></td></tr></tbody></table><p>The anti-slop source is the suite of six skills: the core <code>antislop</code> plus the <code>antislop-ui</code>, <code>antislop-copywriting</code>, <code>antislop-human</code>, <code>antislop-layoutmobile</code>, and <code>antislop-code</code> satellites. It is tracked as a second <a href="/pi-extensions/glossary.html">Skill source</a>, not installed as a package: the mirrored copies ship to every install of this package, and sync keeps them in step. The upstream <code>LICENSE</code> at each source root is copied by hand at adoption, because the sync ignores files that sit outside a skill directory.</p><h2 id="sync-and-adopt" tabindex="-1">Sync and adopt <a class="header-anchor" href="#sync-and-adopt" aria-label="Permalink to &quot;Sync and adopt&quot;">​</a></h2><p><code>skills-manifest.json</code> holds one entry per skill source: repo URL, local root, the upstream root it mirrors, and the Source pin (the upstream commit the whole tree last agreed on).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm run skills:update                # fetch upstream, three-way-merge tracked skills</span></span>
<span class="line"><span>npm run skills:add -- &lt;slug&gt;/&lt;path&gt;  # adopt a new upstream skill, e.g. anti-slop/antislop-ui</span></span></code></pre></div><p><code>skills:update</code> merges every tracked file with <code>git merge-file</code> (base = the pin, theirs = the fetched commit, ours = the local copy). Clean merges apply automatically. A file both sides changed comes back with git conflict markers; resolve it in place, and the pin advances on the next clean sync. Upstream deletes of a skill are reported as orphans and kept in place. New upstream skills are listed as offers and adopted only by <code>skills:add</code>. The Source pin advances only when a sync completes with no conflict and no orphan. The tool never commits, pushes, deletes, or renames.</p><h2 id="local-tweaks" tabindex="-1">Local tweaks <a class="header-anchor" href="#local-tweaks" aria-label="Permalink to &quot;Local tweaks&quot;">​</a></h2><p>Tweaking a skill is editing the file in this repo. A skill sync merges against the tweak, so an upstream change to a tweaked region comes back as a conflict, never as a silent overwrite.</p><p>The vendored antislop core carries one deliberate local tweak (<a href="/pi-extensions/adr/0034-the-vendored-antislop-copy-is-edited-for-a-tracked-tree.html">ADR-0034</a>): the First-Run Install Wizard and the update section are cut, and the mode ladder resolves an unresolved mode to <code>during</code> with the notice <code>antislop active: during (package default).</code> instead of ending the turn to ask, so an unattended session never stalls on the mode question. Steps 1 and 2 of the ladder stay upstream&#39;s: an operator who wants <code>after</code> pins it the upstream way, with <code>npx antislop-ai --mode after</code> for the machine, or by saying so for one session. The suite ships available, not active: no prompt template, initial-context injection, or factory wiring turns it on.</p>`,15)])])}const k=t(l,[["render",i]]);export{u as __pageData,k as default};
